#!/usr/bin/env python3
"""Refresh static navigation and hub from catalog.json; deployment needs no build."""
from pathlib import Path
import html
import json
import re

ROOT = Path(__file__).resolve().parents[1]
items = json.loads((ROOT / 'catalog.json').read_text())
topics = {'foundations': 'Foundations', 'structures': 'Lists & hashing', 'trees': 'Trees',
          'graphs': 'Graphs', 'sorting': 'Sorting', 'analysis': 'Algorithm analysis',
          'case-studies': 'Algorithm case studies', 'languages': 'Programming languages'}
course_names = {'dsa1': 'DSA1', 'dsa2': 'DSA2', 'pl': 'Programming Languages'}
e = html.escape
(ROOT / 'lab-catalog.js').write_text('/* Generated by scripts/sync_catalog.py. */\nwindow.LabCatalog = ' + json.dumps(items, ensure_ascii=False) + ';\n')

for item in items + [{'file': 'index.html'}]:
    path = ROOT / item['file']
    if not path.exists():
        raise RuntimeError(f'Missing catalog page: {path}')
    prefix = '../' if '/' in item['file'] else ''
    groups = ''
    for topic, title in topics.items():
        links = ''.join(f'<a href="{prefix}{x["file"]}"' + (' aria-current="page" class="active"' if x['file'] == item['file'] else '') + f'>{e(x["title"])}</a>' for x in items if x['topic'] == topic)
        groups += f'<div class="lab-nav-group"><p>{title}</p>{links}</div>'
    nav = f'<nav class="course-nav" aria-label="Interactive Lab"><a class="nav-brand" href="{prefix}index.html">Interactive Teaching Lab</a><div class="lab-nav-actions"><a class="hub-link" href="{prefix}index.html">All demonstrations</a><details class="lab-browser"><summary>Browse labs <span aria-hidden="true">▾</span></summary><div class="lab-menu">{groups}</div></details></div></nav>'
    text = path.read_text()
    if item['file'] == 'index.html':
        text = re.sub(r'<title>.*?</title>', '<title>Interactive Teaching Lab — ADTs, Algorithms &amp; Languages</title>', text)
    text = re.sub(r'<nav class="course-nav".*?</nav>', lambda _: nav, text, count=1, flags=re.S)
    for asset, tag in [('lessons.css', f'<link rel="stylesheet" href="{prefix}lessons.css">'),
                       ('lab-catalog.js', f'<script src="{prefix}lab-catalog.js" defer></script>'),
                       ('teaching.js', f'<script src="{prefix}teaching.js" defer></script>')]:
        if not re.search(r'(?:href|src)="(?:\.\./)?' + re.escape(asset) + r'(?:[?"])', text):
            text = text.replace('</head>', tag + '</head>', 1)
    path.write_text(text)

index = ROOT / 'index.html'
text = index.read_text()
before = text[:text.index('<header>')]
chapter_keys = sorted({key for x in items for key in x.get('chapters', [])}, key=lambda k: (k.split(':')[0], int(k.split(':')[1]) if k.split(':')[1].isdigit() else 100))
chapter_options = ''.join(f'<option value="{key}">{course_names[key.split(":")[0]]} · {"Ch. " + key.split(":")[1] if key.split(":")[1].isdigit() else "Syntax & parsing"}</option>' for key in chapter_keys)
header = f'''<header><p class="eyebrow">Explore · Predict · Step through · Practice</p><h1>Interactive Teaching Lab</h1><p class="intro">Explore ADTs, data structures, algorithms, and programming-language theory. Predict a step, try a challenge, and explain what changes.</p><p class="collection-count">{len(items)} demonstrations across {len(topics)} topics</p></header>
<form class="discovery" role="search" id="filters"><div class="field"><label for="searchLabs">Find a demonstration</label><input type="search" id="searchLabs" placeholder="Search LCS, recursion, queues…"></div><div class="field"><label for="topicFilter">Topic</label><select id="topicFilter"><option value="all">All topics</option>{''.join(f'<option value="{k}">{v}</option>' for k,v in topics.items())}</select></div><div class="field"><label for="courseFilter">Course</label><select id="courseFilter"><option value="all">All courses</option>{''.join(f'<option value="{k}">{v}</option>' for k,v in course_names.items())}</select></div><button type="button" id="clearFilters">Clear filters</button></form>
<div class="results"><p id="resultCount" role="status" aria-live="polite">Showing all {len(items)} demonstrations</p><p>Each lab opens in this tab.</p></div>'''
header = header.replace('<button type="button" id="clearFilters">', '<div class="field"><label for="chapterFilter">Chapter</label><select id="chapterFilter"><option value="all">All chapters</option>' + chapter_options + '</select></div><button type="button" id="clearFilters">')
sections = ''
for topic, title in topics.items():
    cards = ''
    for x in items:
        if x['topic'] != topic:
            continue
        courses = ' · '.join(course_names[c] for c in x['courses'])
        search = e(' '.join([x['title'], x['description'], x['objective'], *x['courses']]).lower())
        cards += f'<article class="lab-card" data-search="{search}" data-courses="{" ".join(x["courses"])}" data-chapters="{" ".join(x.get("chapters", []))}"><p class="lab-type">{courses}</p><h3><a href="{x["file"]}">{e(x["title"])}</a></h3><p class="description">{e(x["description"])}</p><a class="open-link" href="{x["file"]}" aria-label="Open {e(x["title"])}">Open lab <span aria-hidden="true">→</span></a></article>'
    sections += f'<section class="topic-section" id="{topic}" data-topic="{topic}" aria-labelledby="{topic}-title"><div class="topic-heading"><h2 id="{topic}-title">{title}</h2></div><div class="labs-grid">{cards}</div></section>'
tail = '''<div id="emptyState" class="empty-state" hidden><h2>No matching demonstrations</h2><p>Try a different keyword, topic, or course.</p></div><footer><span>Interactive Teaching Lab · Learn by experimenting</span><span>Ian Fang, Ph.D. · University of West Florida</span></footer></main>
<style>.discovery{grid-template-columns:minmax(160px,1fr) 150px 150px 170px auto}@media(max-width:1000px){.discovery{grid-template-columns:1fr 1fr}}@media(max-width:600px){.discovery{grid-template-columns:1fr}}</style>
<script>
const search=document.getElementById('searchLabs'),topic=document.getElementById('topicFilter'),course=document.getElementById('courseFilter'),chapter=document.getElementById('chapterFilter');
function filterLabs(){let total=0;for(const section of document.querySelectorAll('.topic-section')){let count=0;for(const card of section.querySelectorAll('.lab-card')){const words=search.value.toLowerCase().trim().split(/\\s+/);const show=(topic.value==='all'||section.dataset.topic===topic.value)&&(course.value==='all'||card.dataset.courses.split(' ').includes(course.value))&&(chapter.value==='all'||card.dataset.chapters.split(' ').includes(chapter.value))&&words.every(w=>card.dataset.search.includes(w));card.hidden=!show;if(show)count++;}section.hidden=!count;total+=count;}document.getElementById('resultCount').textContent='Showing '+total+' of '+document.querySelectorAll('.lab-card').length+' demonstrations';document.getElementById('emptyState').hidden=total>0;}
search.oninput=filterLabs;topic.onchange=chapter.onchange=filterLabs;course.onchange=()=>{if(chapter.value!=='all'&&!chapter.value.startsWith(course.value+':')&&course.value!=='all')chapter.value='all';for(const option of chapter.options)option.hidden=option.value!=='all'&&course.value!=='all'&&!option.value.startsWith(course.value+':');filterLabs();};document.getElementById('filters').onsubmit=e=>e.preventDefault();document.getElementById('clearFilters').onclick=()=>{search.value='';topic.value=course.value=chapter.value='all';for(const option of chapter.options)option.hidden=false;filterLabs();};
</script></body></html>'''
index.write_text(before + header + sections + tail)
print(f'Synchronized {len(items)} labs across {len(topics)} topics.')
